# NEXA Player and Audience System Phase 11 Test Script

Set-Location $PSScriptRoot

python -c "from audience_service import AudienceService; world = {'simulation_day': 12, 'simulation_time': '18:32', 'mayor_approval': 42.0, 'unemployment_rate': 11.0, 'union_anger': 78.0, 'crime_rate': 23.0, 'tax_rate': 20.0, 'mystery_attention': 0.0, 'public_interest': 50.0}; audience = AudienceService(world); player_one = audience.create_player('Amina'); player_two = audience.create_player('Brian'); player_three = audience.create_player('Chao'); print('NEXA Phase 11 Player and Audience Test'); print(); print('PLAYER CREATED:'); print(player_one); print(); investigation = audience.submit_command(player_one['id'], 'Investigate the warehouse.'); print('NATURAL LANGUAGE COMMAND: Investigate the warehouse.'); print('STRUCTURED COMMAND:'); print(investigation['command']); print('WORLD EFFECT:'); print(investigation['result']['world_changes']); print('PLAYER EFFECT:'); print(investigation['result']['player_changes']); print(); mayor_request = audience.submit_command(player_one['id'], 'Talk to the mayor.'); print('NATURAL LANGUAGE COMMAND: Talk to the mayor.'); print('RESULT:'); print(mayor_request['result']['message']); print(); poll = audience.create_tax_poll(); print('POLL CREATED:'); print(poll['question']); print(); [print(audience.cast_vote(poll['id'], player_id, 'increase_taxes')) for player_id in [player_one['id'], player_two['id']]]; print(audience.cast_vote(poll['id'], player_three['id'], 'keep_taxes')); poll_result = audience.close_and_apply_poll(poll['id']); print(); print('COLLECTIVE POLICY RESULT:'); print(poll_result['result']); print('WORLD STATE AFTER VALIDATED COMMANDS AND VOTE:'); print(poll_result['world_state']); print(); print('PASS: A viewer command and an audience vote materially affected permitted NEXA world-state values.')"
